  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from '../../index.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions limit and before while stripping unknown fields and rejecting malformed cursors or limits', () => {
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:05:00.000Z',
      entryCount: 1,
    };
    const listFrame: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const outgoing: OutgoingMessage = listFrame;
    const expectedWithCursor: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {sessionId: 's3', updatedAt: '2026-01-01T00:05:00.000Z'},
    };
    const incoming: IncomingMessage = expectedWithCursor;
    const rejected = [
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', limit: '10'},
      {type: 'list_sessions', limit: Number.NaN},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {sessionId: '', updatedAt: '2026-01-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 'x'.repeat(129), updatedAt: '2026-01-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 42, updatedAt: '2026-01-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 's1', updatedAt: ''}},
      {type: 'list_sessions', before: {sessionId: 's1', updatedAt: 'not-a-date'}},
      {type: 'list_sessions', before: {sessionId: 's1', updatedAt: Number.NaN}},
      {type: 'list_sessions', before: {sessionId: 's1', updatedAt: true}},
    ].map(frame => validateMessage(frame).valid);

    expect({
      outgoingType: outgoing.type,
       bare: validateMessage({type: 'list_sessions', userId: 'u2'}),
      withCursor: validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 's3', updatedAt: '2026-01-01T00:05:00.000Z', extra: 'ignored'},
        userId: 'u2',
      }),
      epochZeroLimit: validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 'x'.repeat(128), updatedAt: 1767225600000},
      }),
      rejected,
    }).toEqual({
      outgoingType: 'session_list',
      bare: {valid: true, data: {type: 'list_sessions'}},
      withCursor: {valid: true, data: incoming},
      epochZeroLimit: {
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 0,
          before: {sessionId: 'x'.repeat(128), updatedAt: 1767225600000},
        },
      },
      rejected: Array(14).fill(false),
    });
  });
});

