import type {IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(raw: unknown): ValidationResult {
  if (!raw || typeof raw !== 'object') {
    return {valid: false, error: 'Message must be a JSON object'};
  }

  const message = raw as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a string "type" field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have a string "content" field'};
  }

  const trimmed = message.content.trim();
  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content exceeds maximum length of ${MAX_CONTENT_LENGTH} characters`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && !isNonNegativeInteger(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const before = message.before === undefined ? undefined : validateBeforeCursor(message.before);
  if (before && !before.valid) {
    return before;
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit !== undefined ? {limit: message.limit} : {}),
      ...(before?.valid ? {before: before.cursor} : {}),
    },
  };
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

function validateBeforeCursor(raw: unknown): {valid: true; cursor: SessionCursor} | ValidationFailure {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const cursor = raw as Record<string, unknown>;
  if (!isValidCursorSessionId(cursor.sessionId)) {
    return {valid: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
  }
  if (!isValidCursorUpdatedAt(cursor.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }

  return {
    valid: true,
    cursor: {
      sessionId: cursor.sessionId,
      updatedAt: cursor.updatedAt,
    },
  };
}

function isValidCursorSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= MAX_SESSION_ID_LENGTH;
}

function isValidCursorUpdatedAt(value: unknown): value is string | number {
  if (typeof value !== 'string' && typeof value !== 'number') return false;
  return Number.isFinite(new Date(value).getTime());
}

